import Foundation

/// Дополнительные этапы (инженерия, внутренняя отделка) и крепёж по этапам
enum StagesExtra {
    // MARK: - Черновые инженерные сети

    static func engineering(_ p: Project, _ r: CalcResults, _ L: HouseLayout) -> BuildStage {
        var s = BuildStage(title: "Инженерные сети: черновой монтаж", icon: "bolt.horizontal", scene: .finish)
        s.goal = "Проложить электрику, воду, канализацию и вентиляцию, пока стены открыты изнутри — до утеплителя и пароизоляции."
        s.when = "после кровли и окон (дом закрыт от дождя), до утепления стен изнутри и стяжки"
        s.steps = [
            "Сначала — план: розетки, выключатели, свет, сантехприборы, коллектор тёплого пола, вентиляционные каналы. Отметить маркером на стойках, сфотографировать после монтажа с рулеткой.",
            "Электрика в деревянном доме: кабель ВВГнг(А)-LS (розетки 3×2.5, свет 3×1.5), скрыто — только в металлической трубе или металлорукаве, открыто — в кабель-канале. Подрозетники — металлические или для деревянных стен, отдельная линия с УЗО 30 мА на каждую группу «мокрых» зон.",
            "Отверстия в стойках — по оси, диаметром не более 1/3 ширины стойки и не ближе 40 мм к кромке; трубы и кабели ведут в зоне обрешётки 25×50 (инсталляционный зазор), чтобы не резать пароизоляцию.",
            "Вода — лучевая разводка: ввод от скважины (стена \(L.entryWall), \(fmt(L.entryOffset, 2)) м от угла) → фильтры → гидроаккумулятор → коллекторы ХВ и ГВ в \(L.collectorRoom.isEmpty ? "техшкафу" : L.collectorRoom.lowercased()). От коллектора к каждой точке — своя цельная труба PE-Xa 16 без соединений в полу/стене (\(L.points.filter { $0.kind == .cold }.count) ХВ + \(L.points.filter { $0.kind == .hot }.count) ГВ, ≈ \(fmt(L.coldLen + L.hotLen, 0)) м). Высоты точек — в таблице ниже.",
            "Канализация: от унитазов Ø110 с уклоном 2 %, от раковин, душа, мойки и стиральной машины Ø50 с уклоном 3 % — к выпуску (стена \(L.outletWall), \(fmt(L.outletOffset, 2)) м от угла, \(fmt(L.outletDepth, 2)) м ниже земли). \(p.floorBase == .slab ? "Под плитой трубы уложены до бетонирования (этап армирования) — здесь только выводы над полом." : p.floorBase == .joists ? "В подполье трубы — на подвесах к балкам с уклоном, в утеплителе; вывод через гильзу в ленте." : "Трубы — в подсыпке под стяжкой.") Фановый стояк Ø110 — через кровлю или вакуумный клапан на стояке.",
            "Точки выводятся строго по расстановке мебели и приборов (схема ниже): сначала решите, где стоят унитаз, раковина, душ, мойка и стиральная машина — переносить точки после стяжки и обшивки дорого.",
            "Вентиляция: вытяжка из кухни, санузлов и котельной, приток в жилые комнаты (клапаны в стенах или приточно-вытяжная установка с рекуператором). Каналы — до утепления.",
            p.floorHeating == .water ? "Тёплый пол: место под коллекторный шкаф, подающие трубы от котла до коллектора — в этом этапе." : "",
            "Проверить: прозвонить линии мегаомметром, опрессовать водопровод (1.5× рабочего давления), пролить канализацию. Только после этого — утеплитель и пароизоляция.",
        ].filter { !$0.isEmpty }
        s.decisions = [
            Decision(title: "Проводка", value: "ВВГнг(А)-LS в металлической трубе / открыто", why: "в зданиях с деревянными конструкциями скрытая проводка — только в негорючих трубах", ref: N.sp256.at("разд. 15")),
            Decision(title: "Отверстия в стойках", value: "≤ 1/3 ширины, по оси", why: "сохранить несущую способность стойки на сжатие", ref: N.sp64.at("разд. 7")),
            Decision(title: "Канализация", value: "уклон отводов 2–3 %", why: "самотёчный отвод без засоров", ref: N.sp30.at("разд. 8")),
            Decision(title: "Вентиляция", value: "вытяжка из кухни и санузлов", why: "удаление влаги — без неё конденсат в каркасе", ref: N.sp60.at("разд. 7")),
        ]
        let A = r.loads.floorArea * Double(max(p.floors, 1))
        s.items = [WorkItem(name: "Кабель ВВГнг(А)-LS 3×2.5 (розетки)", qty: (A * 1.6).rounded(), unit: "м", note: "ориентировочно по площади", digits: 0, price: 95),
                   WorkItem(name: "Кабель ВВГнг(А)-LS 3×1.5 (освещение)", qty: (A * 1.0).rounded(), unit: "м", note: "ориентировочно", digits: 0, price: 65),
                   WorkItem(name: "Металлорукав / труба стальная гибкая Ø20", qty: (A * 2.4).rounded(), unit: "м", digits: 0, price: 45),
                   WorkItem(name: "Подрозетники для полых стен", qty: (A / 3).rounded(.up), unit: "шт", digits: 0, price: 40),
                   WorkItem(name: "Щит с автоматами, УЗО/дифавтоматами", qty: 1, unit: "компл", note: "≈ 12–18 модулей", digits: 0, price: 18000),
] + PlumbingWorks.internalItems(L, p)
        s.figures = [Figure(kind: .furniturePlan, title: "Планировка с мебелью и сантехприборами — по ней выводятся точки", aspect: 0.7),
                     Figure(kind: .plumbingPlan, title: "Разводка воды и канализации: коллектор, лучи PE-Xa, Ø110/Ø50, ввод и выпуск", aspect: 0.75)]
        s.table = PlumbingWorks.pointsTable(L)
        s.tools = ["Дрель с перовыми свёрлами Ø20–32 и коронками", "Перфоратор (вводы через фундамент — по гильзам)", "Индикаторная отвёртка, мультиметр, мегаомметр (аренда)", "Пресс-инструмент для PEX/металлопластика", "Ножовка, труборез", "Уровень, рулетка, маркер"]
        s.fasteners = [
            Fastener(what: "Кабель в трубе/металлорукаве", item: "клипсы для трубы, саморезы 3.5×25", how: "шуруповёрт, через 300–500 мм"),
            Fastener(what: "Подрозетник в стене", item: "подрозетник для полых/деревянных стен с распорками", how: "коронка 68 мм по ГКЛ, затянуть лапки"),
            Fastener(what: "Трубы воды и канализации", item: "клипсы / хомуты с резиновой прокладкой + саморезы 4.5×50", how: "шуруповёрт"),
        ]
        return s
    }

    // MARK: - Внутренняя обшивка

    static func interior(_ p: Project, _ r: CalcResults, _ b: BuildPlan) -> BuildStage {
        let F = b.frame
        let fin = p.interiorFinish
        var s = BuildStage(title: "Внутренняя обшивка: \(fin.short)", icon: "rectangle.portrait", scene: .finish)
        s.goal = "Закрыть стены и потолки изнутри."
        s.when = p.floorSystemEff == .semiDry ? "через 3 суток после полусухой стяжки (стены обшиваются уже от уровня стяжки)" : "после пароизоляции и обрешётки, до чистового пола"
        let floors = max(p.floors, 1)
        let ceil = r.loads.floorArea * Double(floors)
        let wallA = b.wallNet + b.partitionArea * 2
        let gb = p.gklBase
        let strip = max(0, 3.11 - gb - 2.5)
        switch fin {
        case .gkl:
            s.steps = [
                "Порядок: сначала потолок, потом стены. Потолок — ГКЛ поперёк обрешётки 25×50 шаг 400 мм, стыки торцов — на рейке, вразбежку.",
                gb > 0.001 ? "Стены: внизу — целый лист 1200×2500 от стяжки (+10 мм), сверху — полоса \(Drawings.mm(strip)) мм (из листа 1200×2500 режется поперёк)." : "Стены: снизу полоса 600 (лист пополам вдоль), выше целый лист 2500 — 10 + 600 + 2500 = 3110 мм до потолка, отходов нет.",
                "Саморезы для ГКЛ по дереву 3.5×35 (крупная резьба) шаг 250 мм по краю и в поле, отступ 10–15 мм от кромки, шляпка утоплена на 0.5–1 мм.",
                "В санузлах — ГКЛВ, под тяжёлые шкафы и бойлер — закладные из ОСП/доски между стойками до обшивки.",
                "Швы: грунт, серпянка, шпаклёвка в 2 слоя; внешние углы — перфоуголок.",
            ]
            s.items = [WorkItem(name: "ГКЛ 12.5 мм 2500×1200 (гипсокартон)", qty: Double(Int(((wallA + ceil) / 3.0 * 1.1).rounded(.up))), unit: "лист", note: "\(fmt(wallA + ceil, 0)) м², из них ~15 % ГКЛВ", digits: 0, price: Price.gkl),
                       WorkItem(name: "Саморезы для ГКЛ по дереву 3.5×35 (крупная резьба)", qty: (wallA + ceil) * 25 * 0.0015, unit: "кг", digits: 1, price: Price.screwsKg),
                       WorkItem(name: "Шпаклёвка для швов 25 кг + серпянка", qty: ((wallA + ceil) / 60).rounded(.up), unit: "компл", digits: 0, price: 900)]
            s.tools = Guides.finishTools
            s.guides = Guides.finish
        case .boards:
            s.steps = [
                "Вагонка/имитация бруса — НЕ диафрагма: доски на кляммерах не держат стену от перекоса. Поэтому во внутренних стенах и перегородках этого проекта стоят врезные раскосы 25×100 (см. развёртки стен и схему жёсткости), снаружи — ОСП\(p.sheathing.hasBraces ? " и раскосы" : "").",
                "Доски 14×96×3000 — вертикально по горизонтальной обрешётке 25×50 шаг 600: длина доски 3000 = высота стены без подрезки; зазор 10 мм у пола закрывает плинтус, у потолка — галтель.",
                "Влажность досок ≤ 12 %, акклиматизация 2–3 суток в доме. Первую доску — по отвесу, пазом к углу.",
                "Крепление — кляммеры в паз (каждая рейка обрешётки) + оцинкованные гвозди 2×20 или финишные гвозди 1.2×30 в шип под 45° (нейлер-финишер).",
                "Потолок — та же вагонка поперёк обрешётки шаг 400, или ГКЛ.",
                "Обработка: антисептик/лак или масло-воск до монтажа с обеих сторон (меньше коробления).",
            ]
            let boards = Int((wallA / (3.0 * 0.088) * 1.05).rounded(.up))
            s.items = [WorkItem(name: "Вагонка / имитация бруса хвоя 14×96×3000, сорт АВ", qty: Double(boards), unit: "шт", note: "\(fmt(wallA, 0)) м² стен, рабочая ширина 88 мм", digits: 0, price: 210),
                       WorkItem(name: "Кляммеры №2 (уп. 100 с гвоздями)", qty: (Double(boards) * 5 / 100).rounded(.up), unit: "уп", digits: 0, price: 180),
                       WorkItem(name: "ГКЛ 12.5 мм 2500×1200 (потолок)", qty: Double(Int((ceil / 3.0 * 1.08).rounded(.up))), unit: "лист", digits: 0, price: Price.gkl),
                       WorkItem(name: "Масло-воск / лак для дерева 2.5 л", qty: (wallA * 2 / 25).rounded(.up), unit: "шт", digits: 0, price: 2400)]
            s.tools = ["Торцовочная пила", "Нейлер-финишер (гвозди 1.2×30) или молоток 300 г и добойник", "Уровень 2 м, отвес", "Рулетка, угольник", "Лобзик (вырезы под розетки)"]
            s.guides = [Guide(title: "Как зашить стены вагонкой и почему нужны раскосы", steps: [
                "Проверить, что раскосы во внутренних стенах врезаны и прибиты (2 гвоздя 4×100 в каждую стойку) — после обшивки к ним не добраться.",
                "Набить горизонтальную обрешётку 25×50 шаг 600 поверх пароизоляции, гвозди 3×80 / саморезы 4.5×70 в каждую стойку.",
                "Первая доска — у угла пазом к углу, по отвесу; шип прибить финишными гвоздями.",
                "Каждую следующую — паз на шип, подбить через обрезок доски, кляммер в каждую рейку обрешётки.",
                "Последняя доска — по месту, кромку прибить финишными гвоздями, угол закрыть уголком.",
            ], tip: "Дерево «дышит»: оставляйте 1–2 мм в замке и 10 мм у пола и потолка, иначе летом обшивку выгнет.")]
        case .osb:
            s.steps = [
                "ОСП-3 12 мм шлифованная — лист 1250 = 2 шага стоек: крепится по обрешётке 25×50 (зазор под проводку) или прямо к стойкам; работает как вторая диафрагма жёсткости и держит навесные шкафы в любом месте.",
                "Раскладка как снаружи: снизу полоса 625 (лист пополам вдоль), выше целый лист 2500, стыки — на стойках и распорке, зазор 3 мм.",
                "Крепление — саморезы 3.5×35 жёлтые с потайной головкой шаг 150 по краю, 300 в поле (под покраску — шляпки зашпаклевать).",
                "Финиш — грунт по ОСП и краска/лак, или шпаклёвка по стеклохолсту.",
            ]
            s.items = [WorkItem(name: "ОСП-3 12 мм 2500×1250 шлифованная", qty: Double(Int((wallA / 3.125 * 1.08).rounded(.up))), unit: "лист", digits: 0, price: Price.osb12 * 1.1),
                       WorkItem(name: "Саморезы по дереву 3.5×35 жёлтые", qty: wallA * 25 * 0.0015, unit: "кг", digits: 1, price: Price.screwsKg),
                       WorkItem(name: "ГКЛ 12.5 мм 2500×1200 (потолок)", qty: Double(Int((ceil / 3.0 * 1.08).rounded(.up))), unit: "лист", digits: 0, price: Price.gkl)]
            s.tools = ["Циркулярная пила с шиной", "Шуруповёрт с ограничителем, бита PH2", "Уровень 2 м", "Шлифмашина"]
        }
        s.decisions = [Decision(title: "Обшивка стен", value: fin.title, why: fin.isDiaphragm ? "лист, прибитый по контуру, — дополнительная диафрагма жёсткости" : "декоративные доски не работают на перекос — жёсткость внутренних стен обеспечивают раскосы", ref: fin == .gkl ? N.g32614.code : N.g8242.code)]
        if fin == .gkl {
            s.decisions.append(Decision(title: "Раскладка листов", value: gb > 0.001 ? "лист 2500 + полоса \(Drawings.mm(strip))" : "полоса 600 + лист 2500", why: gb > 0.001 ? "стены обшиваются после стяжки: от её уровня до потолка \(Drawings.mm(3.11 - gb)) мм" : "10 + 600 + 2500 = 3110 мм до потолка, лист режется только пополам вдоль", ref: N.g32614.code))
        }
        if let w0 = BuildPlan.wallsExt0First(F) { s.figures = [Figure(kind: .sheetLayout(w0, 2), title: "Раскладка обшивки на стене \(F.walls[w0].name) (изнутри)", aspect: 0.42)] }
        s.fasteners = Fasteners.interior(fin)
        return s
    }
}

/// Крепёж по этапам: что, чем и каким инструментом
enum Fasteners {
    /// Общее правило — показывается на странице соединений и в этапе стен
    static let rule = Guide(title: "Гвозди или саморезы: чем крепить каркас", steps: [
        "Каркас (стойки, обвязки, перемычки, балки) — ГВОЗДИ. Гвоздь гнётся, но не ломается: на срез он надёжнее самореза того же диаметра. Нормы (СП 64) считают узлы каркаса именно на гвоздях.",
        "Гладкие 4×100 (ГОСТ 4028) — для молотка; ершёные/кольцевые 3.1×90 в обойме 34° — для гвоздезабивного пистолета (нейлера), держат на выдёргивание в 1.5–2 раза лучше. Нейлер можно взять в аренду на 1–2 недели — сборка стен ускоряется в 3–4 раза.",
        "Саморезы — там, где нужна стяжка (стены между собой в углу, обвязка к платформе) или разборность: только КОНСТРУКЦИОННЫЕ по дереву 5×90, 6×120, 8×120 (жёлтый цинк, головка Torx/шестигранник, с маркировкой нагрузок). Закручивать ударным шуруповёртом (импакт) битой T30/T40 или головкой 13 мм.",
        "ЧЁРНЫЕ саморезы (фосфатированные, для гипсокартона) в каркас НЕ использовать: они закалённые и хрупкие, ломаются на срез без предупреждения. Их место — только ГКЛ.",
        "Металлические уголки, опоры балок и скобы — на АНКЕРНЫХ (ершёных) гвоздях 4×40 или специальных саморезах 5×35/5×40 для крепёжных изделий, в каждое отверстие, которое указано производителем.",
        "Всё, что снаружи и в контакте с бетоном (контррейка, обрешётка кровли, фасад), — оцинкованный крепёж: чёрный проржавеет и даст потёки на фасаде.",
        "Инструмент: молоток плотницкий 600–800 г (гвозди 100 мм забиваются в 4–6 ударов), нейлер для каркаса, ударный шуруповёрт для длинных саморезов, обычный шуруповёрт с ограничителем — для ОСП, ГКЛ и вагонки.",
    ], tip: "Гвоздь 4×100 в торец стойки забивают через обвязку строго по оси, не ближе 15 мм к кромке. Если гвоздь вылез сбоку — второй рядом, первый загнуть.")

    static let site = [Fastener(what: "Обноска: доска 25×150 к столбикам 50×50", item: "саморезы 4.5×70 (временно — можно чёрные) / гвозди 3×80", how: "шуруповёрт PH2 / молоток")]
    static let form = [Fastener(what: "Щиты опалубки (доски к брускам)", item: "саморезы 4.5×50 изнутри наружу / гвозди 3×70 с загибом", how: "шуруповёрт — разбирать проще"),
                       Fastener(what: "Подкосы и колья", item: "гвозди 4×100", how: "молоток"),
                       Fastener(what: "Стяжки щитов", item: "шпилька М12 в ПВХ-трубке + гайки с шайбами", how: "ключ 19")]
    static let rebar = [Fastener(what: "Пересечения арматуры", item: "проволока вязальная отожжённая Ø1.2 (нарезать по 250–300 мм)", how: "крючок для вязки / вязальный пистолет"),
                        Fastener(what: "Защитный слой", item: "фиксаторы «стульчик» (низ) и «звёздочка» (бока)", how: "вручную, через 0.8–1 м")]
    static let sill = [Fastener(what: "Обвязка к фундаменту", item: "шпилька М12 кл. 5.8 оцинк. на химическом анкере, гайка + шайба DIN 9021", how: "перфоратор Ø14, пистолет для анкера, ключ 19"),
                       Fastener(what: "Угол бруса «в полдерева»", item: "саморезы конструкционные 8×120 (шестигранник) 2 шт / нагель Ø16", how: "ударный шуруповёрт с головкой 13 мм"),
                       Fastener(what: "Лента ППЭ к гидроизоляции", item: "самоклеящаяся", how: "вручную")]
    static let floor = [Fastener(what: "Обвязочная доска к брусу", item: "гвозди 4×100 косо через 400 / кольцевые 3.1×90", how: "молоток / нейлер"),
                        Fastener(what: "Балка к обвязке", item: "опора балки под её сечение + анкерные гвозди 4×40 в каждое отверстие", how: "молоток 400–600 г"),
                        Fastener(what: "Торец балки через обвязочную доску", item: "гвозди 4×100, 3 шт", how: "молоток / нейлер"),
                        Fastener(what: "Черепные бруски 50×50", item: "гвозди 3×80 / саморезы 4.5×70 жёлтые через 300", how: "молоток / шуруповёрт"),
                        Fastener(what: "ОСП-22 к балкам", item: "клей ПУ + саморезы по дереву 4.5×50 жёлтые: 150 по краю, 300 в поле", how: "шуруповёрт, бита PZ2")]
    static let walls = [Fastener(what: "Стойка к обвязке (в торец)", item: "гвозди 4×100 — 2 шт / кольцевые 3.1×90", how: "молоток 800 г / нейлер 34°"),
