                 Fastener(what: "Контробрешётка 50×50", item: "гвозди оцинк. ершёные 3.5×90 через 300", how: "молоток / нейлер"),
                 Fastener(what: "Обрешётка", item: "гвозди оцинк. 3.5×90 — по 2 в каждое пересечение", how: "молоток / нейлер")]
        switch c {
        case .metalTile, .profiledSheet, .seam:
            f.append(Fastener(what: "Кровельные листы", item: "кровельные саморезы 4.8×35 с ЭПДМ-шайбой в цвет (в прогиб волны)", how: "шуруповёрт с магнитной насадкой 8 мм, без перетяга — шайба лишь сплющена"))
